"""Code generation tool. Emits Arduino / MicroPython / ROS 2 source text."""
from __future__ import annotations

import ast
import textwrap
from typing import Any

from ..core.models import ToolResult
from .base import BaseTool


def _arduino_arm(
    theta1_deg: float, theta2_deg: float,
    pin1: int = 9, pin2: int = 10,
) -> str:
    return textwrap.dedent(f"""\
        // Auto-generated by RoboMind
        #include <Servo.h>

        Servo servo1;
        Servo servo2;

        const int PIN_SERVO1 = {pin1};
        const int PIN_SERVO2 = {pin2};

        const float THETA1_DEG = {theta1_deg:.3f}f;
        const float THETA2_DEG = {theta2_deg:.3f}f;

        void setup() {{
            servo1.attach(PIN_SERVO1);
            servo2.attach(PIN_SERVO2);
            servo1.write(90);
            servo2.write(90);
            delay(500);
        }}

        void loop() {{
            servo1.write((int)THETA1_DEG + 90);
            servo2.write((int)THETA2_DEG + 90);
            delay(2000);
        }}
    """)


def _micropython_arm(
    theta1_deg: float, theta2_deg: float,
    pin1: int = 16, pin2: int = 17,
) -> str:
    return textwrap.dedent(f"""\
        # Auto-generated by RoboMind
        from machine import Pin, PWM
        import time

        PIN_SERVO1 = {pin1}
        PIN_SERVO2 = {pin2}

        THETA1_DEG = {theta1_deg:.3f}
        THETA2_DEG = {theta2_deg:.3f}

        def angle_to_duty(angle_deg, freq=50):
            # SG90-style: 0.5ms..2.5ms pulse over 20ms period
            pulse_ms = 0.5 + (angle_deg + 90.0) / 180.0 * 2.0
            return int(pulse_ms / 20.0 * 65535)

        s1 = PWM(Pin(PIN_SERVO1), freq=50)
        s2 = PWM(Pin(PIN_SERVO2), freq=50)

        s1.duty_u16(angle_to_duty(0))
        s2.duty_u16(angle_to_duty(0))
        time.sleep_ms(500)

        while True:
            s1.duty_u16(angle_to_duty(THETA1_DEG))
            s2.duty_u16(angle_to_duty(THETA2_DEG))
            time.sleep(2)
    """)


def _ros2_node(
    theta1_deg: float, theta2_deg: float,
) -> str:
    return textwrap.dedent(f"""\
        # Auto-generated by RoboMind
        import rclpy
        from rclpy.node import Node
        from std_msgs.msg import Float64MultiArray

        THETA1_DEG = {theta1_deg:.3f}
        THETA2_DEG = {theta2_deg:.3f}

        class ArmCommander(Node):
            def __init__(self):
                super().__init__('arm_commander')
                self.pub = self.create_publisher(
                    Float64MultiArray, 'joint_targets', 10)
                self.timer = self.create_timer(0.5, self.publish_targets)

            def publish_targets(self):
                msg = Float64MultiArray()
                msg.data = [THETA1_DEG, THETA2_DEG]
                self.pub.publish(msg)

        def main():
            rclpy.init()
            node = ArmCommander()
            try:
                rclpy.spin(node)
            finally:
                node.destroy_node()
                rclpy.shutdown()

        if __name__ == '__main__':
            main()
    """)


_TARGETS = {
    "arduino": ("cpp", _arduino_arm),
    "micropython": ("python", _micropython_arm),
    "ros2": ("python", _ros2_node),
}


class CodegenTool(BaseTool):
    name = "codegen"
    description = "Generate control code for Arduino, MicroPython, or ROS 2."
    safety_class = "write"

    args_schema = {
        "target": "arduino | micropython | ros2",
        "theta1_deg": "float",
        "theta2_deg": "float",
        "pin1": "int (arduino, micropython)",
        "pin2": "int (arduino, micropython)",
    }
    output_schema = {"target": "str", "language": "str", "code": "str"}

    def run(self, *, step_id: str = "codegen",
            target: str = "arduino", **kwargs: Any) -> ToolResult:
        target = target.lower()
        if target not in _TARGETS:
            return ToolResult(step_id=step_id, ok=False,
                              error=f"unknown target: {target!r} "
                                    f"(expected one of {list(_TARGETS)})")
        language, fn = _TARGETS[target]
        try:
            t1 = float(kwargs.get("theta1_deg", 0.0))
            t2 = float(kwargs.get("theta2_deg", 0.0))
            pin1 = int(kwargs.get("pin1", 9 if target == "arduino" else 16))
            pin2 = int(kwargs.get("pin2", 10 if target == "arduino" else 17))
        except (TypeError, ValueError) as exc:
            return ToolResult(step_id=step_id, ok=False,
                              error=f"invalid argument: {exc}")

        if target == "ros2":
            code = fn(t1, t2)
        else:
            code = fn(t1, t2, pin1, pin2)

        # Validate Python targets
        if language == "python":
            try:
                ast.parse(code)
            except SyntaxError as exc:
                return ToolResult(step_id=step_id, ok=False,
                                  error=f"internal: generated code invalid "
                                        f"(line {exc.lineno}: {exc.msg})")

        return ToolResult(step_id=step_id, ok=True, value={
            "target": target, "language": language, "code": code,
        })